<?php if($items): ?><?= view('platform/order_pv',['items'=>$items]) ?><?php endif ?>
<div class="grid-two"><section class="panel"><h2><?= esc($order['number']) ?> <span class="badge <?= esc($order['status'],'attr') ?>"><?= esc(p_label($order['status'])) ?></span></h2><p class="muted"><?= p_date($order['created_at']) ?></p><table><thead><tr><th>สินค้า</th><th>จำนวน</th><th>รวม</th></tr></thead><tbody><?php foreach($items as $p): ?><tr><td><?= esc($p['name']) ?></td><td><?= $p['quantity'] ?></td><td><?= p_money($p['price_satang']*$p['quantity']) ?></td></tr><?php endforeach ?></tbody></table><div class="actions">สินค้า <?= p_money($order['subtotal_satang']) ?> · ส่วนลด <?= p_money($order['discount_satang']) ?> · ค่าจัดส่ง <?= p_money($order['shipping_satang']) ?></div><p class="price" style="margin-top:18px">ยอดชำระ <?= p_money($order['total_satang']) ?></p><h3>ข้อมูลจัดส่ง</h3><p><?= esc($order['recipient']) ?> · <?= esc($order['phone']) ?><br><?= nl2br(esc($order['address'])) ?></p><?php if($order['tracking']): ?><p>เลขพัสดุ: <strong><?= esc($order['tracking']) ?></strong></p><?php endif ?></section>
<section class="panel"><h2>ชำระเงิน</h2><?php if($order['status']==='awaiting_payment'): ?><p class="description"><?= $bank?esc($bank):'ยังไม่ระบุบัญชีรับโอน กรุณาติดต่อร้านก่อนโอนเงิน' ?></p><form method="post" enctype="multipart/form-data" action="<?= site_url('orders/'.$order['id'].'/payment') ?>" class="stack"><?= csrf_field() ?><label>ยอดโอน (บาท)<input name="amount" type="number" min="0" step="0.01" value="<?= number_format($order['total_satang']/100,2,'.','') ?>" required></label><label>เลขอ้างอิงธุรกรรม<input name="reference" <?= \App\Libraries\Platform\SlipPayments::enabled() ? 'placeholder="เว้นว่างเพื่ออ่านจากสลิป"' : 'required' ?> minlength="3" maxlength="160"></label><label>หลักฐานโอนเงิน<input type="file" name="slip" accept="image/jpeg,image/png,image/webp" required></label><span class="muted"><?= \App\Libraries\Platform\SlipPayments::enabled() ? 'ส่งสลิปให้ผู้ให้บริการตรวจธุรกรรมอัตโนมัติ (ไม่เกิน 4 MB) หากตรวจไม่ได้จะรอเจ้าหน้าที่' : 'ตรวจโดยเจ้าหน้าที่เทียบกับบัญชีธนาคาร · ไม่เกิน 5 MB' ?></span><button>ส่งหลักฐานเพื่อตรวจสอบ</button></form><div class="actions"><?php foreach(['stripe'=>'Stripe','opn'=>'Opn PromptPay'] as $provider=>$label): ?><form method="post" action="<?= site_url('orders/'.$order['id'].'/gateway/'.$provider) ?>"><?= csrf_field() ?><button class="secondary" <?= !(env($provider==='stripe'?'STRIPE_SECRET_KEY':'OPN_SECRET_KEY'))?'disabled':'' ?>><?= $label ?></button></form><?php endforeach ?></div><p class="muted">ช่องทางที่ยังไม่ตั้งค่าจะแสดงเป็นปุ่มปิดใช้งาน</p><?php elseif($order['status']==='gateway_pending'): ?><div class="notice info">รอผลจากผู้ให้บริการ การกลับจากหน้าชำระเงินยังไม่ถือว่าชำระสำเร็จ</div><?php foreach($gateway as $g): if($g['status']!=='ready'||!$g['url']){continue;} ?><p><a class="button" target="_blank" rel="noopener" href="<?= esc($g['url'],'attr') ?>"><?= $g['provider']==='opn'?'เปิด QR PromptPay':'เปิดหน้าชำระเงิน' ?></a></p><?php endforeach ?><?php else: ?><div class="notice"><?= esc(p_label($order['status'])) ?></div><?php endif ?>
<?php foreach($payments as $p): ?><div class="section-note">ชำระ <?= p_money($p['amount_satang']) ?> · <?= esc(p_label($p['status'])) ?><br><?= esc($p['review_note']) ?></div><?php endforeach ?></section></div>
<?php if(in_array($order['status'],['awaiting_payment','payment_review'])): ?><form method="post" action="<?= site_url('orders/'.$order['id'].'/cancel') ?>"><?= csrf_field() ?><button class="secondary">ยกเลิกคำสั่งซื้อที่ยังไม่ชำระ</button></form><?php endif ?>

<?php if(!empty($order['payment_token'])): $receipt=$order['payment_token']; ?>
<section class="panel"><h2>รหัสยืนยันการชำระเงิน (Payment token)</h2>
<?php if($receipt['revoked_at']): ?><div class="notice">รหัสนี้ถูกยกเลิกหลังคืนเงินแล้ว</div>
<?php else: ?><label>สร้างอัตโนมัติหลังยืนยันสลิป<input readonly aria-label="Payment token" value="<?= esc($receipt['token'],'attr') ?>" onclick="this.select()" style="width:100%"></label>
<p class="muted">ออกเมื่อ <?= p_date($receipt['issued_at']) ?> · ใช้อ้างอิงการชำระเงินสำหรับคำสั่งซื้อนี้</p><?php endif ?></section>
<?php endif ?>
